    String[] trytes = { "", "", "" };
    nonTail.store(tangle, snapshot);
    List<TransactionViewModel> transactions = persistAndMapTxs(trytes);
    List<TransactionViewModel> bundleTxs = bundleValidator.validate(tangle, true, snapshot, transactions.get(0).getHash());
    assertTrue("no txs from the invalid bundle should be returned", bundleTxs.isEmpty());
}
