    dbFolder.create();
    logFolder.create();
    tangle.addPersistenceProvider(new RocksDBPersistenceProvider(dbFolder.getRoot().getAbsolutePath(), logFolder.getRoot().getAbsolutePath(), 1000, Tangle.COLUMN_FAMILIES, Tangle.METADATA_COLUMN_FAMILY));
    tangle.init();
    snapshot = SnapshotMockUtils.createSnapshot();
}
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void validateBundleHashOfBundleWithInvalidBundleHash(){
    String[] trytes = { "", "", "" };
    List<TransactionViewModel> transactions = persistAndMapTxs(trytes);
    final byte[] normalizedBundle = new byte[Curl.HASH_LENGTH / ISS.TRYTE_WIDTH];
    BundleValidator.Validity validity = BundleValidator.validateBundleHash(transactions, normalizedBundle);
    assertEquals("the bundle hash should be invalid", BundleValidator.Validity.INVALID, validity);
}
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private List<TransactionViewModel> persistAndMapTxs(String[] trytes){
        return Arrays.stream(trytes).map(Converter::allocatingTritsFromTrytes).map( t -> new TransactionViewModel(t, TransactionHash.calculate(SpongeFactory.Mode.CURLP81, t))).peek( t -> {
            try {
                t.store(tangle, snapshot);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }).collect(Collectors.toList());
    }
/**************TEST HELPER METHOD END*************/
/**************TEST TEARDOWN BEGIN*************/
@After
public void tearDown() throws Exception{
    tangle.shutdown();
}
