        return Arrays.stream(trytes).map(Converter::allocatingTritsFromTrytes).map( t -> new TransactionViewModel(t, TransactionHash.calculate(SpongeFactory.Mode.CURLP81, t))).peek( t -> {
            try {
                t.store(tangle, snapshot);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }).collect(Collectors.toList());
    }
/**************TEST HELPER METHOD END*************/
